import{_ as t,o,c as n,a2 as a}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Independent design workstation","description":"","frontmatter":{},"headers":[],"relativePath":"websites/independent-design.md","filePath":"websites/independent-design.md"}'),i={name:"websites/independent-design.md"};function s(r,e,d,l,p,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="independent-design-workstation" tabindex="-1">Independent design workstation <a class="header-anchor" href="#independent-design-workstation" aria-label="Permalink to &quot;Independent design workstation&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release — source-reviewed draft</p><p>TransferBook+ v0.7.9 source baseline. Availability depends on installed release, permissions and configuration. Live publication is not established by this guide.</p></div><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Use the standalone Theme Studio kit to design and exchange packages without requiring access to operational data. This workflow is for the design workstation, not the documentation workstation.</p><h2 id="prerequisites-and-workflow" tabindex="-1">Prerequisites and workflow <a class="header-anchor" href="#prerequisites-and-workflow" aria-label="Permalink to &quot;Prerequisites and workflow&quot;">​</a></h2><ol><li>Use an approved portable kit prepared from the matching application source. The reference guide documents <code>npm run export:theme-studio-kit</code> on the engineering workstation.</li><li>On the design workstation use the kit&#39;s <code>START_THEME_STUDIO.ps1</code> and open its loopback address <code>http://127.0.0.1:4310</code>. Follow the kit&#39;s own version-specific installation instructions.</li><li>Duplicate an existing style, adjust tokens, layout, localized text and approved assets, then inspect contrast and device previews.</li><li>Use <strong>Save Local Draft</strong> and export <code>.tbtheme.json</code>; for multi-page Website Studio work export <code>.tbsite.json</code> as applicable.</li><li>Transfer only the validated design package to the intended operator for review and import. Do not transfer credentials or customer data.</li></ol><h2 id="expected-result-and-troubleshooting" tabindex="-1">Expected result and troubleshooting <a class="header-anchor" href="#expected-result-and-troubleshooting" aria-label="Permalink to &quot;Expected result and troubleshooting&quot;">​</a></h2><p>The independent kit needs no application database or operator login. It does not deploy the product. If a package is incompatible, confirm the kit version with engineering and re-export; never bypass validation. See <a href="./portable-packages.html">portable packages</a>.</p>',8)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
